using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Linq;
using System.IO;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (EditorApplication.isPlaying)
                throw new System.Exception("Edit required");
            foreach (var actor in s.GetComponentsInChildren<InvestigationActor>())
            {
                var ts = actor.GetComponentsInChildren<Transform>(true);
                actor.head = ts.FirstOrDefault(t => t.name == "head");
                actor.leftUpper = ts.FirstOrDefault(t => t.name == "upperL");
                actor.rightUpper = ts.FirstOrDefault(t => t.name == "upperR");
                actor.leftFore = ts.FirstOrDefault(t => t.name == "foreL");
                actor.rightFore = ts.FirstOrDefault(t => t.name == "foreR");
            }

            var tool = s.clipTu.Find("Tool_in_hand");
            if (tool)
            {
                tool.SetParent(s.clipTu.GetComponentsInChildren<Transform>().Single(t => t.name == "handL"), false);
                tool.localPosition = Vector3.zero;
                tool.localRotation = Quaternion.identity;
            }

            s.clipRepair.localPosition = new Vector3(.8f, 3.4f, 1.1f);
            s.clipRepair.localScale = Vector3.one * .7f;
            // First repaired gate has no scripted force on the original scene: all tests are on the model.
            var shell = s.transform.Find("Workshop_GDD36/WorkshopShell_SourceFBX");
            var b = shell.GetComponent<MeshRenderer>().bounds;
            File.WriteAllText("Test/KetQua/investigation_r102/workshop-placement.txt", "Workshop world bounds=" + b + "\nActor refs=" + s.GetComponentsInChildren<InvestigationActor>().Length + "\nOld puppet source pieces still present=" + Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Count(t => t.name == "ConRoi_Head_SameAsMinh"));
            EditorSceneManager.MarkSceneDirty(s.gameObject.scene);
            EditorSceneManager.SaveScene(s.gameObject.scene);
            r.Log("Pose references filled, tool attached to actual hand bone, R12 positioned at repair hands. Scene saved.");
        }
    }
}

